fn sqlite_snapshot_step_native_preflight_and_bare_binary_text_admission(){
    let snapshot=fixture();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let remaining=control.allocation_remaining_bytes();snapshot.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut control).unwrap();let vector:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/💰️backing/🔣️.json")).unwrap();let slots=vector["preflightFrontierSlots"].as_array().unwrap().iter().map(|value|usize::try_from(value.as_u64().unwrap()).unwrap()).sum::<usize>();let paid=slots*std::mem::size_of::<std::slice::Iter<'_,StepValue>>();assert_eq!(control.allocation_remaining_bytes(),remaining-paid);for(limit,success)in[(paid,true),(paid-1,false)]{let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:limit,..SqliteDatabaseLimits::default()});let result=snapshot.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut control);if success{result.unwrap();assert_eq!(control.allocation_remaining_bytes(),0);}else{assert_eq!(result.unwrap_err().kind,semio_framework_value::ValueRefusalKind::OwnershipLimit);}}let mut finite=fixture();finite.entities[0].args=vec![StepValue::Integer(i64::MIN),StepValue::Real(-0.0),StepValue::Reference(u64::MAX)];let codec=store::ArtifactCodec::bare::<StepSnapshot,crate::standards::v_ap214::subsets::base::schema::mutations::StepMutation>(STDIO_STEP_DOCUMENT_SCHEMA);let provider=codec.snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.step".into(),standard:"ap214".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<StepSnapshot as store::ArtifactPack>::encode_pack(&finite)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<StepSnapshot as store::ArtifactDsl>::print_dsl(&finite))};let database=(provider.export)(&finite.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let restored=(provider.import)(&finite.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(restored,payload);}assert!(finite.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).is_err());assert!(finite.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
}
